import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";

export default function Login() {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [successMessage, setSuccessMessage] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isSent, setIsSent] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();

  useEffect(() => {
    const params = new URLSearchParams(location.search);
    const errorType = params.get("error");
    
    if (errorType === "expired_link") {
      setError("⏰ Your magic link has expired. Please request a new one.");
      window.history.replaceState({}, document.title, "/");
    } else if (errorType === "invalid_link") {
      setError("❌ Invalid magic link. Please request a new one.");
      window.history.replaceState({}, document.title, "/");
    } else if (errorType === "session_expired") {
      setError("⏰ Your session has expired. Please login again.");
      window.history.replaceState({}, document.title, "/");
    }
    
    // Check if session expired flag is set
    const sessionExpired = sessionStorage.getItem('session_expired');
    if (sessionExpired === 'true') {
      setError("⏰ Your session has expired. Please login again.");
      sessionStorage.removeItem('session_expired');
    }
  }, [location]);

  const createAuth = async (e) => {
    e.preventDefault();
    setIsLoading(true);
    setError("");
    setSuccessMessage("");

    try {
      const res = await axios.post("http://localhost:3597/api/user/login", {
        email,
      });
      
      setSuccessMessage("✅ Login link sent successfully! Check your email.");
      setIsSent(true);
      localStorage.setItem("userToken", res.data.token);
      
    } catch (error) {
      const errorMsg = error.response?.data?.message || "Something went wrong. Please try again.";
      setError(`❌ ${errorMsg}`);
      setIsSent(false);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative flex items-center justify-center overflow-hidden"
      style={{
        background: 'linear-gradient(135deg, #0a0f1e 0%, #1a1f35 50%, #0d1a2b 100%)'
      }}
    >
      {/* Your existing JSX here */}
      <div className="relative z-10 w-full max-w-md px-4">
        {/* Logo and form as before */}
        <div className="bg-white/5 backdrop-blur-xl rounded-2xl border border-white/10 shadow-2xl p-8">
          {/* Error and success messages */}
          {error && (
            <div className="bg-red-500/10 border border-red-500/20 rounded-lg p-4 mb-4">
              <p className="text-red-400 text-sm">{error}</p>
            </div>
          )}
          
          {successMessage && (
            <div className="bg-green-500/10 border border-green-500/20 rounded-lg p-4 mb-4">
              <p className="text-green-400 text-sm">{successMessage}</p>
            </div>
          )}
          
          {/* Rest of your form */}
        </div>
      </div>
    </div>
  );
}
